Here's the component with loading and error states, an HTTP status check, and cleanup if the component unmounts mid-request:

```jsx
import { useEffect, useState } from "react";

export default function UserList() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();

    async function load() {
      try {
        const res = await fetch("/api/users", { signal: controller.signal });
        if (!res.ok) {
          throw new Error(`Request failed with status ${res.status}`);
        }
        const data = await res.json();
        setUsers(data);
      } catch (err) {
        if (err.name !== "AbortError") {
          setError(err.message || "Something went wrong");
        }
      } finally {
        setLoading(false);
      }
    }

    load();
    return () => controller.abort();
  }, []);

  if (loading) return <p>Loading users…</p>;
  if (error) return <p role="alert">Couldn't load users: {error}</p>;
  if (users.length === 0) return <p>No users found.</p>;

  return (
    <ul>
      {users.map((u) => (
        <li key={u.id}>{u.name}</li>
      ))}
    </ul>
  );
}
```

**What changed:**
- `res.ok` check — `fetch` doesn't throw on 404/500, so we throw ourselves.
- `try/catch` around the request and JSON parsing, with the message stored in `error`.
- `AbortController` cancels the request on unmount, and we ignore the resulting `AbortError`.
- Separate UI for loading, error, and empty states.

